<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script><script src="assets/js/qr-camera.js?v=20261114"></script>
<script>
const TR_API='controllers/clssTransporte.php';let trTab='vehiculos',trDatos={transportes:[],clientes:[],monedas:[],productos:[],conductores:[]},trViajes=[],trDespachos=[],trDetalles=[],tcOficialDespacho=null;
const trModalVeh=new bootstrap.Modal(document.getElementById('modalTransporte')),trModalViaje=new bootstrap.Modal(document.getElementById('modalViaje')),trModalDesp=new bootstrap.Modal(document.getElementById('modalDespacho')),trModalCliente=new bootstrap.Modal(document.getElementById('modalClienteDespacho'));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function trCall(accion,data={}){const r=await fetch(TR_API,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:new URLSearchParams({accion,...data})});const raw=await r.text();let j;try{j=JSON.parse(raw)}catch{const resumen=raw.replace(/<script[\s\S]*?<\/script>/gi,' ').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim().slice(0,240);if(r.redirected||/login|iniciar sesi[oó]n/i.test(raw))throw Error('La sesión pudo haber vencido. Vuelve a iniciar sesión y repite la acción.');throw Error(`El servidor respondió con HTML en vez de JSON (HTTP ${r.status}). ${resumen||'Respuesta vacía.'}`)}if(!j.success)throw Error(j.message||'Error');return j}
const msg=(title,text,icon='error')=>Swal.fire({title,text,icon});
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{trTab=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));document.getElementById('btnPrincipal').innerHTML=trTab==='vehiculos'?'<i class="fa-solid fa-plus"></i> Nuevo transporte':'<i class="fa-solid fa-plus"></i> Nuevo viaje';document.getElementById('trBuscar').placeholder=trTab==='vehiculos'?'Buscar vehículo por nombre o placa':'Buscar por placa o transportista';document.getElementById('trEstadoFiltro').style.display=trTab==='vehiculos'?'':'none';renderTransporte()});
document.getElementById('trBuscar').addEventListener('input',renderTransporte);document.getElementById('trEstadoFiltro').addEventListener('change',cargarTransportes);
async function cargarTodo(){try{await Promise.all([cargarTransportes(),cargarDatosDespacho(),cargarViajes()])}catch(e){msg('No se pudo cargar',e.message)}}
async function cargarTransportes(){const j=await trCall('LISTARTRANSPORTES',{texto:document.getElementById('trBuscar').value,estado:document.getElementById('trEstadoFiltro').value});trDatos.transportes=j.transportes;renderTransporte()}
async function cargarDatosDespacho(){const j=await trCall('LISTARDATOSDESPACHO');trDatos={...trDatos,...j};llenarSelectsDespacho()}
async function cargarViajes(){const j=await trCall('LISTARVIAJES');trViajes=j.viajes;trDespachos=j.despachos;trDetalles=j.detalles;renderTransporte()}
function accionPrincipal(){trTab==='vehiculos'?abrirVehiculo():abrirViaje()}
function renderTransporte(){const c=document.getElementById('trContenido');if(trTab==='vehiculos'){const q=document.getElementById('trBuscar').value.toLowerCase();const rows=(trDatos.transportes||[]).filter(x=>(`${x.nombre} ${x.placa||''}`).toLowerCase().includes(q));c.innerHTML=rows.length?`<div class="table-responsive"><table class="pc-table"><thead><tr><th>Vehículo</th><th>Placa</th><th>Capacidad</th><th>Estado</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td><b>${esc(x.nombre)}</b></td><td>${esc(x.placa||'—')}</td><td>${x.capacidad_carga?`${esc(x.capacidad_carga)} kg`:'—'}</td><td>${x.deleted_at?'Inactivo':'Activo'}</td><td>${x.deleted_at?'':`<button class="btn btn-sm btn-outline-primary" onclick="editarVehiculo(${Number(x.id)})">Editar</button> <button class="btn btn-sm btn-outline-danger" onclick="borrarVehiculo(${Number(x.id)})">Desactivar</button>`}</td></tr>`).join('')}</tbody></table></div>`:'<div class="tr-muted p-3">No hay vehículos para mostrar.</div>';return;}const q=document.getElementById('trBuscar').value.toLowerCase();const viajes=(trViajes||[]).filter(v=>`${v.transporte_nombre} ${v.placa} ${JSON.stringify(v.js_transportistas)}`.toLowerCase().includes(q));c.innerHTML=viajes.length?`<div class="tr-grid">${viajes.map(v=>renderViaje(v)).join('')}</div>`:'<div class="tr-muted p-3">No hay viajes registrados.</div>'}
function renderViaje(v){const drivers=parseJson(v.js_transportistas),stops=parseJson(v.js_ubicaciones_ruta),sales=trDespachos.filter(s=>Number(s.movimiento_transporte_id)===Number(v.id)),cerrado=sales.length>0&&sales.every(s=>s.estado!=='C');return `<article class="tr-card"><div class="d-flex justify-content-between gap-2"><div><h3>${esc(v.transporte_nombre||'Vehículo')} ${v.placa?`· ${esc(v.placa)}`:''}</h3><div class="tr-muted">Viaje #${v.id} · ${esc(v.fecha_translado)} · ${v.capacidad_carga?`${esc(v.capacidad_carga)} kg`:''}</div></div><span class="tr-state ${cerrado?'E':'C'}">${cerrado?'Despachos cerrados':'En ruta'}</span></div><div class="mt-2"><b>Transportistas</b><br>${drivers.map(d=>`<span class="tr-chip">${esc(typeof d==='string'?d:d.nombre||'')}</span>`).join('')||'—'}</div><div class="mt-2"><b>Ruta y carga por parada</b>${stops.map((s,i)=>{const nombre=typeof s==='string'?s:s.ubicacion||s.nombre||'';const carga=sales.filter(x=>Number(x.ubicacion_ruta_indice)===i);return `<div class="tr-stop"><b>${i+1}. ${esc(nombre)}</b><div class="tr-muted">${carga.length?carga.map(x=>`${esc(x.cliente)} · ${x.estado==='E'?'entregado':x.estado==='R'?'rechazado':'en ruta'}`).join('<br>'):'Sin despacho asignado'}</div></div>`}).join('')||'<div class="tr-stop">Agrega paradas al editar el viaje.</div>'}</div><div class="d-flex justify-content-between mt-2"><span class="tr-muted">${sales.length} despacho(s)</span><b>S/ ${Number(v.monto_total).toFixed(2)} total base</b></div><div class="d-flex flex-wrap gap-2 mt-3"><button class="btn btn-sm btn-primary" onclick="abrirDespacho(${Number(v.id)},'${esc(v.transporte_nombre||'')}')">+ Cargar parada</button><button class="btn btn-sm btn-outline-primary" onclick="editarViaje(${Number(v.id)})">Editar viaje</button><button class="btn btn-sm btn-outline-danger" onclick="borrarViaje(${Number(v.id)})">Eliminar</button></div>${sales.map(s=>renderDespacho(s)).join('')}</article>`}
function renderDespacho(s){const lines=trDetalles.filter(x=>x.registro_uid===s.registro_uid);const uid=String(s.registro_uid||'');const fuente=s.tipo_cambio_fuente==='oficial'?'oficial API':s.tipo_cambio_fuente==='calle'?'tipo de calle':'local';const totalPEN=Number(s.monto_total_pen??s.monto)||0;const totalCobro=Number(s.monto_total_cobro??s.monto)||0;const estado=s.estado==='E'?'Entregado':s.estado==='R'?'Rechazado':'En ruta';return `<div class="border-top mt-3 pt-2"><div class="tr-dispatch-head d-flex justify-content-between align-items-start gap-2"><div><b>${esc(s.cliente)}</b><div class="tr-muted">Parada: <b>${esc(s.ubicacion_destino||'Sin ubicación')}</b> · Despacho ${esc(uid.slice(0,8))} · ${esc(s.fecha_venta)}</div><div class="tr-muted">Base: S/ ${totalPEN.toFixed(2)} · Cobro: ${esc(s.moneda)} ${totalCobro.toFixed(2)} · Cambio ${esc(fuente)} ${Number(s.tipo_cambio_aplicado||1).toFixed(4)}</div></div><div class="tr-dispatch-actions"><a class="btn btn-sm btn-outline-secondary" href="controllers/ticketPdf.php?despacho=${encodeURIComponent(uid)}" target="_blank" rel="noopener"><i class="fa-solid fa-receipt"></i> Ticket actualizado</a><span class="tr-state ${s.estado==='E'?'E':s.estado==='R'?'R':'C'}">${estado}</span>${s.estado==='C'?`<button class="btn btn-sm btn-success" onclick="estadoDespacho('${uid}','E')"><i class="fa-solid fa-circle-check"></i> Confirmar entrega</button><button class="btn btn-sm btn-outline-danger" onclick="estadoDespacho('${uid}','R')">Rechazar</button>`:''}</div></div>${s.estado==='C'?'<div class="form-text mt-1">Al llegar a este cliente, confirma aquí la entrega de su mercadería.</div>':''}${lines.map(l=>`<div class="tr-load-line"><span>${esc(l.producto)} · ${esc(l.cantidad)} ${esc(l.unidad_venta_corto||'')} · S/ ${Number(l.sub_total_calcular).toFixed(2)}</span>${s.estado==='C'&&l.linea_uid?`<button type="button" class="btn btn-sm btn-outline-danger" onclick="devolverItemDespacho('${uid}','${esc(l.linea_uid)}',${Number(l.cantidad)})">Devolver cantidad</button>`:''}</div>`).join('')}</div>`}
function parseJson(x){try{const v=typeof x==='string'?JSON.parse(x):x;return Array.isArray(v)?v:[]}catch{return[]}}
