async function actualizarTipoCambioDespacho({resetManual=false}={}){const moneda=trDatos.monedas.find(m=>String(m.id)===String(despacho_moneda.value))?.codigo||'PEN';const fuente=document.getElementById('despacho_tc_fuente').value;const fuenteWrap=document.getElementById('despacho_tc_fuente_wrap'),tcWrap=document.getElementById('despacho_tc_wrap'),campo=document.getElementById('despacho_tc'),info=document.getElementById('despacho_tc_info');if(moneda==='PEN'){fuenteWrap.hidden=true;tcWrap.hidden=true;campo.value='1';campo.disabled=true;info.textContent='PEN: no requiere tipo de cambio.';return}fuenteWrap.hidden=false;tcWrap.hidden=false;campo.disabled=fuente==='oficial';campo.readOnly=false;if(fuente==='oficial')info.textContent='Consultando tipo de cambio oficial de Chequea…';else if(tcOficialDespacho&&tcOficialDespacho.moneda===moneda){if(resetManual||!campo.value||campo.dataset.moneda!==moneda)campo.value=Number(tcOficialDespacho.venta).toFixed(4);campo.dataset.moneda=moneda;info.textContent=`Cambio de calle manual. Referencia oficial ${moneda}: compra ${Number(tcOficialDespacho.compra).toFixed(4)} / venta ${Number(tcOficialDespacho.venta).toFixed(4)} (${tcOficialDespacho.fecha}).`}else info.textContent='Ingresa el tipo de cambio de calle acordado.';if(fuente==='calle'&&tcOficialDespacho?.moneda===moneda)return;try{const r=await trCall('CONSULTARTIPOCAMBIO',{fecha:despacho_fecha.value,moneda});if(!r.success)throw Error(r.message||'No se pudo consultar el tipo de cambio oficial.');tcOficialDespacho={...r.tipo_cambio,moneda};if(fuente==='oficial'){campo.value=Number(tcOficialDespacho.venta).toFixed(4);campo.dataset.moneda=moneda;info.textContent=`${moneda} · compra ${Number(tcOficialDespacho.compra).toFixed(4)} / venta ${Number(tcOficialDespacho.venta).toFixed(4)} (${tcOficialDespacho.fecha}). Fuente oficial: Chequea API.`}else{if(resetManual||!campo.value||campo.dataset.moneda!==moneda)campo.value=Number(tcOficialDespacho.venta).toFixed(4);campo.dataset.moneda=moneda;info.textContent=`Cambio de calle manual. Referencia oficial ${moneda}: compra ${Number(tcOficialDespacho.compra).toFixed(4)} / venta ${Number(tcOficialDespacho.venta).toFixed(4)} (${tcOficialDespacho.fecha}).`}}catch(e){if(fuente==='oficial'){campo.value='';info.textContent=`${e.message} Cambia a “De calle” para registrar una tasa manual.`}else info.textContent=`No se pudo consultar la referencia oficial. Ingresa la tasa de calle acordada. ${e.message}`}}
