function agregarLineaDespacho(productoId,paquete=null){const p=trDatos.productos.find(x=>Number(x.id)===Number(productoId));if(!p)return;const row=document.createElement('div');row.className='tr-line';row.innerHTML=`<div class="tr-product-wrap"><input type="hidden" class="tr-product" value="${Number(p.id)}"><div class="tr-line-product">${esc(p.codigo)} · ${esc(p.descripcion)}</div><div class="tr-product-info">Stock actual: <b>${Number(p.stock||0).toLocaleString('es-PE',{maximumFractionDigits:2})} ${esc(p.unidad||'UND')}</b> · Unidad de venta: <b>${esc(p.unidad||'UND')}</b>${paquete?`<br>Paquete #${Number(paquete.empaquetado_id)}: ${Number(paquete.cantidad_disponible_paquete).toLocaleString('es-PE',{maximumFractionDigits:2})} ${esc(paquete.unidad_paquete||'UND')} disponibles · hasta ${Number(paquete.cantidad_venta_disponible||0).toLocaleString('es-PE',{maximumFractionDigits:2})} ${esc(p.unidad||'UND')} de venta.`:''}</div></div><div class="tr-field"><label>Cantidad (${esc(p.unidad||'UND')})</label><input class="form-control tr-qty" type="number" min="0.01" step="0.01" value="${paquete?Number(paquete.cantidad_venta_disponible||0):''}" placeholder="Cantidad" required></div><div class="tr-field"><label>Precio unitario (S/)</label><input class="form-control tr-price" type="number" min="0" step="0.01" placeholder="Precio en soles" required></div><div class="tr-field"><label>Descuento de línea (S/)</label><input class="form-control tr-disc" type="number" min="0" step="0.01" value="" placeholder="Opcional" title="Descuento opcional de esta línea"></div><div class="tr-field"><label>Bulto (QR)</label><input class="form-control tr-pack" type="number" min="1" step="1" placeholder="ID bulto" value="${paquete?Number(paquete.empaquetado_id):''}" ${paquete?'readonly title="Vinculado al QR escaneado"':''}></div><button class="btn btn-outline-danger tr-remove" type="button" title="Quitar producto" aria-label="Quitar producto" onclick="this.parentElement.remove();calcularDespacho()"><i class="fa-solid fa-trash"></i></button>`;row.querySelectorAll('input').forEach(el=>el.addEventListener('input',calcularDespacho));document.getElementById('despachoLineas').appendChild(row);if(paquete)row.querySelector('.tr-qty').focus();calcularDespacho()}
async function escanearPaqueteDespacho(){const codigo=await new Promise(resolve=>window.abrirLectorQR(resolve));if(!codigo)return;try{const r=await trCall('BUSCARPAQUETEQR',{codigo_qr:codigo});const p=r.paquete;if(document.querySelector(`#despachoLineas .tr-pack[value="${Number(p.empaquetado_id)}"]`)){msg('Paquete ya agregado',`El bulto #${p.empaquetado_id} ya está en este despacho.`,'info');return}const producto=trDatos.productos.find(x=>Number(x.id)===Number(p.producto_id));if(!producto)throw Error('El producto del paquete está inactivo o no aparece disponible.');agregarLineaDespacho(p.producto_id,p);msg('QR leído','Se cargó el producto y se vinculó el paquete. Ingresa la cantidad en unidad de venta y el precio en soles.','success')}catch(e){msg('No se pudo cargar el QR',e.message)}}
function calcularDespacho(){let total=0;document.querySelectorAll('#despachoLineas .tr-line').forEach(r=>{total+=(Number(r.querySelector('.tr-qty').value)||0)*(Number(r.querySelector('.tr-price').value)||0)-(Number(r.querySelector('.tr-disc').value)||0)});total=Math.max(0,total-(Number(despacho_descuento.value)||0));const moneda=trDatos.monedas.find(m=>String(m.id)===String(despacho_moneda.value));const codigo=moneda?.codigo||'PEN';const tc=codigo==='PEN'?1:(Number(despacho_tc.value)||0);const cobro=tc>0?(codigo==='PEN'?total:total/tc):null;document.getElementById('despachoTotal').textContent=`Total base en soles: S/ ${total.toFixed(2)}${cobro===null?' · Esperando tipo de cambio':codigo==='PEN'?'':` · Cobro estimado: ${moneda?.simbolo||codigo} ${cobro.toFixed(2)} ${codigo}`}`}
