document.getElementById('formDespacho').onsubmit=async e=>{e.preventDefault();const items=[...document.querySelectorAll('#despachoLineas .tr-line')].map(r=>({producto_id:r.querySelector('.tr-product').value,cantidad:r.querySelector('.tr-qty').value,precio:r.querySelector('.tr-price').value,descuento:r.querySelector('.tr-disc').value,empaquetado_id:r.querySelector('.tr-pack').value}));const selected=Boolean(despacho_cliente_ruc.value),clienteRucFinal=despacho_cliente_ruc.value||'99999999',clienteNombreFinal=selected?despacho_cliente_texto.value.trim():'Clientes Varios';if(!despacho_vendedor.value){msg('Selecciona vendedor','El ticket necesita identificar al vendedor.','warning');return}if(['deposito','transferencia'].includes(despacho_pago_medio.value)&&!despacho_pago_cuenta.value){msg('Selecciona cuenta','Indica la cuenta receptora para este pago.','warning');return}if(!despacho_destino.value){msg('Selecciona una parada','Elige a qué punto de la ruta va esta carga.','warning');return}try{const saved=await trCall('GUARDARDESPACHO',{movimiento_transporte_id:despacho_viaje_id.value,cliente_ruc:clienteRucFinal,cliente:clienteNombreFinal,vendedor_usuario_id:despacho_vendedor.value,pago_medio:despacho_pago_medio.value,pago_cuenta_id:despacho_pago_cuenta.value,pago_referencia:despacho_pago_referencia.value,moneda_id:despacho_moneda.value,fecha_venta:despacho_fecha.value,fuente_tipo_cambio:despacho_tc_fuente.value,tipo_cambio:despacho_tc.value,descuento_general:despacho_descuento.value,ubicacion_ruta_indice:despacho_destino.value,items:JSON.stringify(items)});trModalDesp.hide();await Promise.all([cargarViajes(),cargarDatosDespacho()]);const url=`controllers/ticketPdf.php?despacho=${encodeURIComponent(saved.registro_uid)}`;await Swal.fire({title:'Carga registrada',text:'El stock y el kardex se actualizaron. Descarga o imprime el ticket interno.',icon:'success',html:`<a class="btn btn-primary mt-2" href="${url}" target="_blank" rel="noopener"><i class="fa-solid fa-receipt"></i> Abrir ticket de carga</a>`,showConfirmButton:false,showCloseButton:true})}catch(e){msg('No se pudo guardar',e.message)}};
async function estadoDespacho(registro_uid,estado){const ok=await Swal.fire({title:estado==='E'?'¿Confirmar la entrega?':'¿Rechazar este despacho?',text:estado==='E'?'La mercadería quedará registrada como entregada a este cliente.': 'El despacho se cerrará y la mercadería volverá al stock.',icon:estado==='E'?'question':'warning',showCancelButton:true,confirmButtonText:estado==='E'?'Sí, entregado':'Sí, rechazar',cancelButtonText:'Volver'});if(!ok.isConfirmed)return;try{await trCall('CAMBIARESTADODESPACHO',{registro_uid,estado});const local=trDespachos.find(x=>x.registro_uid===registro_uid);if(local)local.estado=estado;renderTransporte();msg(estado==='R'?'Despacho rechazado':'Entrega registrada',estado==='R'?'Se devolvió el stock y se actualizó el estado.':'La parada quedó marcada como entregada.','success');cargarViajes().catch(err=>console.warn('No se pudo refrescar la lista de viajes:',err));if(estado==='R')cargarDatosDespacho().catch(err=>console.warn('No se pudo refrescar el catálogo de productos:',err))}catch(e){msg('No se pudo actualizar',e.message)}}
async function devolverItemDespacho(registro_uid,linea_uid,cantidadDisponible){const respuesta=await Swal.fire({title:'Devolver mercadería al stock',text:`Asignado a este cliente: ${cantidadDisponible}. Indica cuánto regresa al almacén.`,input:'number',inputValue:cantidadDisponible,inputAttributes:{min:'0.01',max:String(cantidadDisponible),step:'0.01',inputmode:'decimal'},showCancelButton:true,confirmButtonText:'Devolver cantidad',cancelButtonText:'Cancelar',preConfirm:valor=>{const cantidad=Number(valor);if(!Number.isFinite(cantidad)||cantidad<=0||cantidad>cantidadDisponible)return 'Ingresa una cantidad mayor a 0 y no superior a la asignada.';return cantidad}});if(!respuesta.isConfirmed)return;try{const resultado=await trCall('DEVOLVERITEMDESPACHO',{registro_uid,linea_uid,cantidad_devolver:respuesta.value});await Promise.all([cargarViajes(),cargarDatosDespacho()]);await Swal.fire({title:'Devolución registrada',text:resultado.message||'El stock y el despacho se actualizaron.',icon:'success',html:`<a class="btn btn-primary mt-2" href="controllers/ticketPdf.php?despacho=${encodeURIComponent(registro_uid)}" target="_blank" rel="noopener"><i class="fa-solid fa-receipt"></i> Ver ticket actualizado</a>`,showConfirmButton:false,showCloseButton:true})}catch(e){msg('No se pudo corregir',e.message)}}
document.addEventListener('blur',event=>{const input=event.target;if(input instanceof HTMLInputElement&&input.type==='number'&&input.value!==''){const value=Number(input.value);if(Number.isFinite(value))input.value=String(value)}},true);
document.addEventListener('DOMContentLoaded',cargarTodo);
</script>
<script>
let clientesDespachoResultados=[];let clienteDespachoTimer=null;
document.getElementById('despacho_cliente_texto').addEventListener('input',function(){const texto=this.value.trim(),box=document.getElementById('despacho_cliente_resultados');document.getElementById('despacho_cliente_ruc').value='';document.getElementById('despacho_cliente_seleccionado').textContent='Selecciona un cliente de la lista de resultados.';clearTimeout(clienteDespachoTimer);if(texto.length<2){box.style.display='none';return}clienteDespachoTimer=setTimeout(()=>{clientesDespachoResultados=trDatos.clientes.filter(c=>`${c.razon_social||''} ${c.nombre_comercial||''} ${c.ruc||''}`.toLocaleLowerCase('es').includes(texto.toLocaleLowerCase('es'))).slice(0,15);box.innerHTML=clientesDespachoResultados.map((c,i)=>`<button type="button" data-cliente-index="${i}"><b>${esc(c.razon_social)}</b>${c.nombre_comercial?` (${esc(c.nombre_comercial)})`:''}<div class="disp">${esc(c.ruc)}</div></button>`).join('')||'<div class="p-2 text-muted">No se encontraron clientes.</div>';box.style.display='block'},180)});
document.getElementById('despacho_cliente_resultados').addEventListener('click',e=>{const b=e.target.closest('[data-cliente-index]');if(!b)return;const c=clientesDespachoResultados[Number(b.dataset.clienteIndex)];if(!c)return;despacho_cliente_ruc.value=c.ruc;despacho_cliente_texto.value=c.razon_social;despacho_cliente_seleccionado.textContent=`Seleccionado: ${c.razon_social} (${c.ruc})`;despacho_cliente_resultados.style.display='none'});
document.addEventListener('click',e=>{if(!e.target.closest('.pc-venta-cliente-buscador'))document.getElementById('despacho_cliente_resultados').style.display='none'});
function abrirRegistroClienteDespacho(){document.getElementById('formClienteDespacho').reset();trModalCliente.show();setTimeout(()=>{const backdrops=document.querySelectorAll('.modal-backdrop');const top=backdrops[backdrops.length-1];if(top)top.classList.add('tr-backdrop-cliente');document.getElementById('modalClienteDespacho').style.zIndex='1070'},20)}
document.getElementById('modalClienteDespacho').addEventListener('hidden.bs.modal',()=>{document.getElementById('modalClienteDespacho').style.zIndex='';if(document.getElementById('modalDespacho').classList.contains('show')){document.body.classList.add('modal-open');document.querySelectorAll('.modal-backdrop.tr-backdrop-cliente').forEach(b=>b.remove())}});
document.getElementById('nuevo_cliente_dni').addEventListener('input',function(){this.value=this.value.replace(/\D/g,'')});
document.getElementById('formClienteDespacho').addEventListener('submit',async e=>{e.preventDefault();const ruc=document.getElementById('nuevo_cliente_dni').value.trim(),nombre=document.getElementById('nuevo_cliente_nombre').value.trim();if(!/^\d{8}$|^\d{11}$/.test(ruc)||!nombre){msg('Revisa los datos','Ingresa DNI de 8 dígitos o RUC de 11 dígitos y el nombre.','warning');return}try{const existe=await fetch('controllers/clssProveedor.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({accion:'OBTENERPROVEEDOR',ruc})}).then(r=>r.json());if(existe.success){msg('Cliente ya registrado','Busca el RUC/DNI en el campo Cliente y selecciónalo.','warning');return}const respuesta=await fetch('controllers/clssProveedor.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({accion:'GUARDARPROVEEDOR',ruc,razon_social:nombre,nombre_comercial:document.getElementById('nuevo_cliente_comercial').value.trim(),js_tipo:JSON.stringify(['cliente']),telefonos_contacto:'[]',solo_nuevo_cliente:'1',js_consulta_api:''})}).then(r=>r.json());if(!respuesta.success)throw Error(respuesta.message||'No se pudo registrar el cliente.');trModalCliente.hide();await cargarDatosDespacho();despacho_cliente_ruc.value=ruc;despacho_cliente_texto.value=nombre;despacho_cliente_seleccionado.textContent=`Seleccionado: ${nombre} (${ruc})`;msg('Listo','Cliente registrado y seleccionado.','success')}catch(err){msg('No se pudo registrar',err.message)}});
</script>
